import React, { useState, useEffect, useContext } from 'react';
import { AppContext } from '../context/AppContext';
import { useNavigate } from 'react-router-dom';

const OrdersPage = () => {
  const [orders, setOrders] = useState([]);
  const { fetchOrders, loading, user } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadOrders();
  }, [user]);

  const loadOrders = async () => {
    const data = await fetchOrders();
    setOrders(data);
  };



  return (
    <div className="max-w-md mx-auto mt-6 px-1">
      <h1 className="text-xl font-bold mb-4 text-gray-800">My Orders</h1>
      {loading && <p className="text-center">Loading...</p>}
      {orders.length === 0 ? (
        <p className="text-center text-xl text-gray-600 py-8">No orders yet</p>
      ) : (
        <div className="grid gap-4">
          {orders.map(order => {
            const orderDate = new Date(order.orderDate);
            const deliveryDate = new Date(orderDate.getTime() + 7 * 24 * 60 * 60 * 1000);

            return (
              <div key={order._id} className="bg-white py-6 px-3 rounded-lg shadow-sm border border-gray-200 min-h-48">
                <div className="flex gap-12 h-full">
                  <div className="flex-shrink-0">
                    <img 
                      src={order.bookId?.image || 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=300&h=400&fit=crop'} 
                      alt={order.bookId?.title || 'Book'} 
                      className="w-32 h-44 object-cover rounded shadow-sm"
                      onError={(e) => {
                        e.target.src = 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=300&h=400&fit=crop';
                      }}
                    />
                  </div>
                  <div className="flex-grow flex flex-col justify-start py-2">
                    <h3 className="text-base font-bold mb-2">{order.bookId?.title}</h3>
                    <p className="text-sm mb-1"><span className="font-semibold">Author:</span> {order.bookId?.author}</p>
                    <p className="text-sm mb-1"><span className="font-semibold">Quantity:</span> {order.quantity} books</p>
                    <p className="text-sm mb-1"><span className="font-semibold">Price:</span> ₹{order.bookId?.price} each</p>
                    <p className="font-bold text-lg mb-3">Total: ₹{order.totalAmount}</p>

                    <div className="text-sm space-y-1">
                      <p><span className="font-semibold">Order Date:</span> {orderDate.toLocaleDateString()}</p>
                      <p><span className="font-semibold">Delivery Date:</span> {deliveryDate.toLocaleDateString()}</p>
                      <p><span className="font-semibold">Status:</span> <span className="capitalize font-semibold">{order.status}</span></p>
                      <p>Delivered to: {order.shippingAddress?.city}</p>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default OrdersPage;
